function esPalindromoLimpio(s) {
  const ok = (c) => /[a-z0-9]/i.test(c);
  let i = 0, j = s.length - 1;
  while (i < j) {
    while (i < j && !ok(s[i])) i++;
    while (i < j && !ok(s[j])) j--;
    if (s[i].toLowerCase() !== s[j].toLowerCase()) return false;
    i++;
    j--;
  }
  return true;
}

solution.python:
def esPalindromoLimpio(s):
    ok = lambda c: c.isascii() and c.isalnum()
    i, j = 0, len(s) - 1
    while i < j:
        while i < j and not ok(s[i]):
            i += 1
        while i < j and not ok(s[j]):
            j -= 1
        if s[i].lower() != s[j].lower():
            return False
        i += 1
        j -= 1
    return True
